function cpFunctionSpan(string $source, string $name): array {
    $tokens=token_get_all($source,TOKEN_PARSE);$offset=0;$matches=[];
    for($i=0,$n=count($tokens);$i<$n;$i++) {
        $t=$tokens[$i];$text=is_array($t)?$t[1]:$t;
        if(is_array($t)&&$t[0]===T_FUNCTION) {
            $j=$i+1;while($j<$n&&is_array($tokens[$j])&&in_array($tokens[$j][0],[T_WHITESPACE,T_COMMENT,T_DOC_COMMENT],true))$j++;
            if(is_array($tokens[$j]??null)&&$tokens[$j][0]===T_STRING&&$tokens[$j][1]===$name) {
                $length=0;$depth=0;$body=false;
                for($k=$i;$k<$n;$k++) {
                    $u=$tokens[$k];$length+=strlen(is_array($u)?$u[1]:$u);
                    if($u==='{'||(is_array($u)&&in_array($u[0],[T_CURLY_OPEN,T_DOLLAR_OPEN_CURLY_BRACES],true))){$depth++;$body=true;}
                    if($u==='}'&&--$depth===0&&$body){$matches[]=[$offset,$length];break;}
                }
            }
        }
